def has_cycle(graph, start_node=None):
    """
    Detects a cycle in a directed graph using DFS.
    graph: dict where keys are nodes and values are lists of neighbors.
    start_node: optional starting node; if None, checks all nodes.
    Returns True if a cycle exists, False otherwise.
    """
    # States: 0 = unvisited, 1 = visiting (in current path), 2 = visited
    state = {node: 0 for node in graph}

    def dfs(node):
        if state[node] == 1:
            return True  # Cycle found: back edge to current path
        if state[node] == 2:
            return False  # Already fully processed

        state[node] = 1  # Mark as visiting
        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True
        state[node] = 2  # Mark as visited
        return False

    # Check all nodes to handle disconnected graphs
    for node in graph:
        if state[node] == 0 and dfs(node):
            return True
    return False
